import { chromium, devices } from "@playwright/test";
const [label] = process.argv.slice(2);
const A = "http://localhost:3100/ai/artifacts/b2d45c04-0c66-42eb-880d-be9a2ab1bcd8";
const browser = await chromium.launch();
for (const theme of ["light", "dark"]) {
  for (const [view, opts] of [["mobile", devices["iPhone 13"]], ["desktop", { viewport: { width: 1280, height: 720 } }]]) {
    const context = await browser.newContext({ ...opts, storageState: "e2e/.auth.json", colorScheme: theme });
    await context.addCookies([{ name: "moneo-theme", value: theme, url: A }]);
    const page = await context.newPage();
    for (const [name, q] of [["page", ""], ["cards", "?tab=cards"], ["card2", "?tab=cards&card=ac300092-166e-4744-b0a3-5bff672c1a39"]]) {
      await page.goto(A + q);
      const section = page.getByRole("region", { name: "Artifact", exact: true });
      await section.scrollIntoViewIfNeeded();
      await page.waitForTimeout(2500);
      await section.screenshot({ path: `.qa/shots/${label}/section-${name}-${view}-${theme}.png` });
      if (label === "after" && name === "cards") {
        await page.getByRole("group", { name: "Size" }).scrollIntoViewIfNeeded();
        const more = page.getByLabel("More Home options");
        await more.click();
        await page.waitForTimeout(300);
        await section.screenshot({ path: `.qa/shots/${label}/section-menu-${view}-${theme}.png` });
      }
    }
    await context.close();
  }
}
await browser.close();

